int main(int argc, char *argv[]) {
    ctags_context_t *ctx = ctags_context_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create context\n");
        return 1;
    }

    // Parse command line arguments
    int opt;
    struct option long_options[] = {
        {"help", no_argument, NULL, 'h'},
        {"version", no_argument, NULL, 'v'},
        {"output-format", required_argument, NULL, 256},
        {"format", required_argument, NULL, 257},
        {"language-force", required_argument, NULL, 258},
        {"sort", required_argument, NULL, 259},
        {"recurse", no_argument, NULL, 'R'},
        {"append", no_argument, NULL, 'a'},
        {"list-languages", no_argument, NULL, 260},
        {"list-kinds", optional_argument, NULL, 261},
        {"list-output-formats", no_argument, NULL, 262},
        {"fields", required_argument, NULL, 263},
        {NULL, 0, NULL, 0}
    };

    int option_index = 0;
    while ((opt = getopt_long(argc, argv, "f:o:e:x:u:n:N:R:aDhV?", long_options, &option_index)) != -1) {
        switch (opt) {
            case 'h':
            case '?':
                print_help(argv[0]);
                ctags_context_free(ctx);
                return 0;
            case 'v':
                print_version();
                ctags_context_free(ctx);
                return 0;
