            case 'o':
                ctx->output_file = optarg;
                break;
            case 'e':
                ctx->output_format = OUTPUT_FORMAT_ETAGS;
                break;
            case 'x':
                ctx->output_format = OUTPUT_FORMAT_XREF;
                break;
            case 'u':
                ctx->sort_mode = SORT_NONE;
                break;
            case 'n':
                ctx->excmd = EXCMD_NUMBER;
                break;
            case 'N':
                ctx->excmd = EXCMD_PATTERN;
                break;
            case 'R':
                ctx->recurse = 1;
                break;
            case 'a':
                ctx->append = 1;
                break;
            case 'D':
                // Handle -D macro definition later
                break;
            case 'V':
                ctx->verbose = 1;
                break;
            case 256: // --output-format
                if (strcmp(optarg, "json") == 0) ctx->output_format = OUTPUT_FORMAT_JSON;
                else if (strcmp(optarg, "e-ctags") == 0) ctx->output_format = OUTPUT_FORMAT_ETAGS;
                else if (strcmp(optarg, "etags") == 0) ctx->output_format = OUTPUT_FORMAT_ETAGS;
                else if (strcmp(optarg, "xref") == 0) ctx->output_format = OUTPUT_FORMAT_XREF;
                else if (strcmp(optarg, "u-ctags") == 0) ctx->output_format = OUTPUT_FORMAT_UCTAGS;
                break;
            case 257: // --format
                ctx->tag_format = atoi(optarg);
                break;
            case 258: // --language-force
                ctx->language_force = optarg;
                break;
            case 259: // --sort
                if (strcmp(optarg, "no") == 0) ctx->sort_mode = SORT_NONE;
                else if (strcmp(optarg, "foldcase") == 0) ctx->sort_mode = SORT_FOLDCASE;
                else ctx->sort_mode = SORT_YES;
                break;
            case 260: // --list-languages
                ctags_list_languages();
                ctags_context_free(ctx);
                return 0;
            case 261: // --list-kinds
                if (optarg) {
                    ctags_list_kinds(optarg);
                } else {
                    ctags_list_kinds("all");
                }
                ctags_context_free(ctx);
                return 0;
            case 262: // --list-output-formats
                ctags_list_output_formats();
                ctags_context_free(ctx);
                return 0;
            case 263: // --fields
                ctx->fields = optarg;
                break;
        }
    }

    // Collect input files
    for (int i = optind; i < argc; i++) {
        ctags_add_input_file(ctx, argv[i]);
    }

    // If no files, print help if not already handled
    if (ctx->num_input_files == 0 && ctx->output_format != OUTPUT_FORMAT_JSON) {
        // This might be okay, or we might need to read from stdin
    }

    // Process files and generate tags
    int result = ctags_process_files(ctx);

    ctags_context_free(ctx);
    return result;
}
